import re

RECOGNIZERS = [
    (re.compile(r"\b[\w.+-]+@[\w-]+\.[\w.]+\b"), "EMAIL"),
    (re.compile(r"\b\d{4}[ -]?\d{4}[ -]?\d{4}[ -]?\d{4}\b"), "CARD"),
    (re.compile(r"\b\+?\d[\d -]{8,}\d\b"), "PHONE"),
    # + NER pass for names, addresses, IDs
]

def redact(text: str) -> tuple[str, dict]:
    mapping = {}
    for rx, kind in RECOGNIZERS:
        def sub(m, kind=kind):
            key = f"<{kind}_{len(mapping) + 1}>"
            mapping[key] = m.group(0)
            return key
        text = rx.sub(sub, text)
    return text, mapping

def restore(text: str, mapping: dict) -> str:
    for key, value in mapping.items():
        text = text.replace(key, value)
    return text

# Request flow:
#   user text → redact() → LLM API → restore() → user
#   provider sees placeholders only · mapping never leaves the request scope
